import 'package:flutter/material.dart';import '../../services/auth_service.dart';import '../auth/login_screen.dart';
class ProfileScreen extends StatelessWidget{const ProfileScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Profile')),body:FutureBuilder<String?>(future:AuthService().email,builder:(c,s)=>ListView(padding:const EdgeInsets.all(24),children:[const CircleAvatar(radius:38,child:Icon(Icons.person,size:40)),const SizedBox(height:16),Text(s.data??'',textAlign:TextAlign.center,style:const TextStyle(fontSize:18)),const SizedBox(height:30),FilledButton.icon(onPressed:()async{await AuthService().logout();if(c.mounted)Navigator.pushAndRemoveUntil(c,MaterialPageRoute(builder:(_)=>const LoginScreen()),(_)=>false);},icon:const Icon(Icons.logout),label:const Text('Logout'))]));}
